  public const string Qualification="Experimental one owned SOLID translation in world/document raw mm. Observed bounds/COG/inventory/properties and saved-byte checks only, not full topology. Independent verification required. No save, selection, inverse or retry; unknown/unfinished execution fences this copy.";
  static Dictionary<string,object> Clone(Dictionary<string,object> data){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(data));}
  static string Artifact(string root,string folder,string id){if(!EntitySets.Hex(id,32))throw new ArgumentException("Invalid artifact ID.");string path=Path.Combine(root,folder,id+".json");OwnedCopies.NoReparse(path);return path;}
  static double Numeric(object value){if(!(value is int||value is long||value is double||value is decimal||value is float))throw new ArgumentException("Finite numeric measurement required.");double n=Program.StrictDouble(value);if(double.IsNaN(n)||double.IsInfinity(n))throw new ArgumentException("Non-finite measurement.");return n;}
  static double[] Vector(object value,int length){var list=value as IList;if(list==null||list.Count!=length)throw new ArgumentException("Measurement array shape differs.");return list.Cast<object>().Select(Numeric).ToArray();}
  internal static bool Near(double[] a,double[] b){return a.Length==b.Length&&a.Zip(b,(x,y)=>Math.Abs(x-y)<=0.000001).All(x=>x);}
  static void BoundsValid(double[] values){if(values.Length!=6||values.Any(v=>double.IsNaN(v)||double.IsInfinity(v))||values[0]>values[1]||values[2]>values[3]||values[4]>values[5])throw new ArgumentException("Invalid direct world bounds.");}
