  internal static int Target(OwnedOperationPlans.Dependencies dependencies) {
   if(!Equals(dependencies.Plan["operation"],"translate_entities")||dependencies.Keys.Length!=1||dependencies.Keys[0][0]!=40)throw new InvalidOperationException("Only one explicit SOLID translation is qualified by this executor.");
   if(!Equals(dependencies.Expected["lengthUnitsRaw"],"mm")||Numeric(dependencies.Expected["lengthUnitFactorRaw"])!=1)throw new InvalidOperationException("Resolved document raw mm units required.");
   int native=dependencies.Keys[0][1];var g=Solid(dependencies.Expected,native)["geometry"] as Dictionary<string,object>;
   if(g==null||!Equals(g["lengthUnitsRaw"],"mm")||!Equals(g["coordinateFrame"],"world"))throw new InvalidOperationException("World COG in raw mm required.");Vector(g["cogRaw"],3);Numeric(g["volumeRaw"]);Numeric(g["areaRaw"]);return native;
  }
