   BoundsValid(boundsBefore);BoundsValid(boundsAfter);double[] moved=boundsBefore.Select((v,i)=>v+delta[i/2]).ToArray();if(!Near(boundsAfter,moved))throw new InvalidOperationException("Direct world bounds do not match translation.");
   var expected=Clone(before);var normalized=Clone(after);var original=(Dictionary<string,object>)Solid(expected,nativeId)["geometry"];var actual=(Dictionary<string,object>)Solid(normalized,nativeId)["geometry"];
