   foreach(string field in new[]{"volumeRaw","areaRaw"}){double a=Numeric(actual[field]),b=Numeric(original[field]);if(Math.Abs(a-b)>Math.Max(0.000000001,Math.Abs(b)*0.000000001))throw new InvalidOperationException("Translation changed raw "+field);actual[field]=original[field];}
   if(EntitySets.ObservedDigest(expected)!=EntitySets.ObservedDigest(normalized))throw new InvalidOperationException("Other observed geometry/inventory/context/units changed.");
  }
  static void Match(Dictionary<string,object> packet,OwnedOperationPlans.Dependencies d,OwnedCopies.OwnershipLease lease) {
   if(EntitySets.Expiry(packet["expiresUtc"])!=d.Expires||!Equals(packet["nativeObservedPropertiesSha256"],d.Digest)||!Equals(packet["windowContextSha256"],d.Binding["windowContextSha256"])||!Equals(packet["copyId"],d.Binding["copyId"])||!Equals(packet["ownershipSha256"],d.Binding["ownershipSha256"])||!Equals(packet["workingSha256"],lease.Inspection["workingSha256"]))throw new IOException("Packet dependency identity or working bytes changed.");
  }
  internal static string FencePath(string root,string copyId){if(!EntitySets.Hex(copyId,32))throw new ArgumentException("Invalid copy ID.");string path=Path.Combine(root,"workingcopies",copyId,"mutation-fence.json");OwnedCopies.NoReparse(path);return path;}
  static Dictionary<string,object> Result(string state){return new Dictionary<string,object>{{"state",state},{"bridgeVersion",Program.ReleaseVersion},{"timestampUtc",DateTime.UtcNow.ToString("o")},{"geometryMutationAttempted",false},{"contextChangeAttempted",false},{"cadSaveAttempted",false},{"retryAllowed",false},{"qualification",Qualification}};}
