     if(File.Exists(fence)||File.Exists(claim))throw new InvalidOperationException("Copy fenced or local intent already claimed; inspect original journal. No replay.");
     d.Check(lease,context,result);int composite=context.Composite(type,native);double[] bounds=surface?null:context.Bounds(composite);if(!surface)BoundsValid(bounds);var capture=surface?OwnedSurfaceTranslation.Capture(d.Expected,d.Expires,context,native,grid):null;var windows=context.Windows();if(DocumentBindings.WindowDigest(windows)!=(string)packet["windowContextSha256"])throw new InvalidOperationException("Execution window context differs.");var saved=WorkingCopyOpen.SavedHashes(windows);
     var plan=new Dictionary<string,object>(parameters){{"schemaVersion",surface?2:1},{"operationId",id},{"operation",surface?"translate_owned_surface":"translate_owned_solid"},{"executionEnabled",true},{"ownedOperationId",args["ownedOperationId"]},{"ownedOperationSha256",args["ownedOperationSha256"]},{"copyId",packet["copyId"]},{"ownershipSha256",packet["ownershipSha256"]},{"workingSha256",packet["workingSha256"]},{"inspectionRequestId",d.Binding["inspectionRequestId"]},{"inspectionSha256",d.Binding["inspectionSha256"]},{"windowContextSha256",packet["windowContextSha256"]},{"nativeId",native},{"compositeId",composite},{"vectorRaw",vector},{"boundsBeforeWorldRaw",bounds},{"createdUtc",DateTime.UtcNow.ToString("o")}};
