     result["savedFilesUnchanged"]=true;result["sameWorkerPostconditionsPassed"]=true;result["guardPasses"]=2;result["sameContextObservationReads"]=6;result["postconditionReadPasses"]=2;result["commandCalls"]=1;result["state"]="owned_translation_executed_unverified";journal.Append("executed_unverified",new Dictionary<string,object>{{"sameWorkerPostconditionsPassed",true},{"independentVerificationRequired",true}});result["recordedJournalState"]=journal.State;result["copyFenced"]=true;
