  }
  public static void ValidateVerification(Dictionary<string,object> args) {
   string[] ids={"executionRequestId","inspectionRequestId","listingRequestId"},shas={"executionReceiptSha256","inspectionSha256","listingSha256"};if(args.Count!=9||ids.Any(k=>!args.ContainsKey(k)||!EntitySets.Hex(args[k],32))||shas.Any(k=>!args.ContainsKey(k)||!EntitySets.Hex(args[k],64))||!args.ContainsKey("windowNumber")||!(args["windowNumber"] is int)||!args.ContainsKey("modelId")||!(args["modelId"] is int)||!args.ContainsKey("expiresUtc"))throw new ArgumentException("Invalid independent translation proof parameters.");EntitySets.Expiry(args["expiresUtc"]);
  }
