   try {ValidateVerification(args);string id=(string)args["executionRequestId"];using(var proofs=new OwnedOperationPlans.Proofs()) {
    var receipt=proofs.Json(Artifact(root,"responses",id),(string)args["executionReceiptSha256"],16000000);if(!Equals(receipt["operationId"],id)||!new[]{"owned_translation_executed_unverified","owned_translation_outcome_unknown"}.Contains((string)receipt["state"])||!Equals(receipt["geometryMutationAttempted"],true)||!Equals(receipt["cadSaveAttempted"],false)||!Equals(receipt["contextChangeAttempted"],false)||!Equals(receipt["returnCode"],1))throw new InvalidOperationException("Returned successful COM command receipt required, not an interrupted command.");
