  public static Dictionary<string,object> Run(string requestId,Dictionary<string,object> args,bool verify,bool surface=false) {
   try {Config c=Program.ReadConfig();if(!c.IsGeneralCore||!c.ownedTranslationsExperimental||surface&&!c.ownedSurfaceTranslationsExperimental)throw new InvalidOperationException("Experimental owned translation disabled.");if(verify)ValidateVerification(args);else if(surface)OwnedSurfaceTranslation.Validate(args);else OwnedOperationPlans.ValidateParameters(args,false);Directory.CreateDirectory(Path.Combine(Program.Root,"operations"));using(var guard=new FileStream(Path.Combine(Program.Root,"operations","executor.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))using(var context=new DocumentBindings.ComContext(c))return verify?Verify(Program.Root,args,context,surface):Execute(Program.Root,requestId,args,context,surface);}catch(Exception error){var result=Result(verify?"owned_translation_verification_rejected":"owned_translation_rejected_before_change");result["error"]=error.Message;return result;}
  }
